gbCt(){return"\u0420\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u044e \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f. \u0412\u0441\u0451 \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u043e, \u0431\u0435\u0437 \u0441\u0443\u0435\u0442\u044b \u0438 \u043d\u0435\u0440\u0432\u043e\u0432."},
